/*
 * A124376  Number triangle with column k generated by
 *          x^k*(1+2*k*x+C(k,2)*x^2)/(1-x)^(k+1).
 * https://oeis.org/A124376
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  easy, nonn, tabl
 * Formula:   a(n) = T(r,k) where r = floor((sqrt(8*n+1)-1)/2), k = n -
 *            r*(r+1)/2 and T(r,k) = sum_{j=0..min(2,r-k)} binom(k,j) *
 *            binom(r-j,k) * C(2,j)
 * Range:     u8 n <= 38, u16 n <= 125, u32 n <= 477, u64 n <= 1917,
 *            u128 n <= 7684, big any n
 * Helpers:   binom
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Here C(2,0)=1, C(2,1)=2, C(2,2)=1.  The binomial helper is provided by the utils library. */
#include "../utils/binom.h"

seq_t a(idx_t n)
{
    /* Find row r such that r*(r+1)/2 <= n < (r+1)*(r+2)/2. */
    idx_t r = 0;
    idx_t lo = 0;
    idx_t hi = n;                   /* hi can be n because r <= n for n>=0. */
    while (lo <= hi) {
        idx_t mid = lo + ((hi - lo) >> 1);
        unsigned __int128 mid_sum = (unsigned __int128)mid * (mid + 1) / 2;
        if (mid_sum <= (unsigned __int128)n) {
            r = mid;
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }

    /* Column index within the row. */
    idx_t k = n - (idx_t)((unsigned __int128)r * (r + 1) / 2);

    /* Maximum j that can contribute (C(2,j) is non‑zero only for j<=2). */
    idx_t j_max = (r >= k) ? ((r - k) < 2 ? (r - k) : 2) : 0;

    seq_t result = 0;
    for (idx_t j = 0; j <= j_max; ++j) {
        seq_t bin1 = binom(k, j);           /* C(k,j) */
        seq_t bin2 = binom(r - j, k);       /* C(r-j,k) */
        seq_t coef = (j == 1) ? 2 : 1;       /* C(2,0)=1, C(2,1)=2, C(2,2)=1 */
        seq_t term = bin1 * bin2 * coef;
        result += term;
    }

    return result;
}
